"""Write docs/API.md (and docs/openapi.json) from the application's live OpenAPI schema."""

from __future__ import annotations

import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from onconova.api.app import app  # noqa: E402

ROOT = Path(__file__).resolve().parents[2]


def main() -> None:
    schema = app.openapi()
    (ROOT / "docs").mkdir(exist_ok=True)
    (ROOT / "docs" / "openapi.json").write_text(json.dumps(schema, indent=2))
    lines = [
        "# OncoNova AI API reference",
        "",
        "Generated by `make report` from the live OpenAPI schema (`docs/openapi.json`). Interactive docs: "
        "`http://127.0.0.1:8010/docs` while the API is running.",
        "",
        "> " + schema["info"]["description"],
        "",
        "**Conventions**",
        "",
        "- Auth: in `dev` mode, localhost only; in `api_key` mode send `X-API-Key`. Roles: viewer < researcher < admin.",
        "- Errors: `{\"error\": {\"code\", \"message\", \"details\"}, \"request_id\"}`. No stack traces are returned.",
        "- Missing inputs return HTTP 200 with `{\"status\": \"unavailable\", \"reason\", \"missing_inputs\", \"how_to_fix\"}`, never a guess.",
        "- Binary volumes: raw little-endian arrays (C order, z-y-x) with `X-Shape`, `X-Spacing`, `X-Origin`, "
        "`X-Direction`, `X-Dtype`, `X-Scale`, `X-Offset` headers; value = raw x scale + offset.",
        "- Lesion sources: `reference`, `annotation`, or `pred:<model_id>`.",
        "",
    ]
    by_tag: dict[str, list[tuple[str, str, dict]]] = {}
    for path, ops in schema["paths"].items():
        for method, op in ops.items():
            by_tag.setdefault((op.get("tags") or ["other"])[0], []).append((method.upper(), path, op))
    for tag, ops in by_tag.items():
        lines += [f"## {tag.capitalize()}", "", "| Method | Path | Description |", "|---|---|---|"]
        for method, path, op in ops:
            desc = (op.get("description") or op.get("summary") or "").replace("\n", " ").replace("|", "\\|")
            lines.append(f"| `{method}` | `{path}` | {desc} |")
        lines.append("")
        for method, path, op in ops:
            params = op.get("parameters", [])
            body = op.get("requestBody", {}).get("content", {})
            if not params and not body:
                continue
            lines.append(f"**`{method} {path}`**")
            for p in params:
                sch = p.get("schema", {})
                typ = sch.get("type") or "/".join(x.get("type", "?") for x in sch.get("anyOf", [])) or "string"
                lines.append(f"- `{p['name']}` ({p['in']}, {typ}{', required' if p.get('required') else ''})")
            if "application/json" in body:
                ref = body["application/json"]["schema"].get("$ref", "").split("/")[-1]
                fields = schema["components"]["schemas"].get(ref, {}).get("properties", {})
                lines.append(f"- JSON body `{ref}`: " + ", ".join(f"`{k}`" for k in fields))
            lines.append("")
    (ROOT / "docs" / "API.md").write_text("\n".join(lines))
    print(f"Wrote docs/API.md ({sum(len(v) for v in by_tag.values())} endpoints)")


if __name__ == "__main__":
    main()
